#!/bin/sh
# SPDX-License-Identifier: BSD-3-Clause
# Copyright (c) 2026, Bo Maryniuk and RavenBSD contributors
#
# Start the one-connection host TLS server before QEMU boots. The server exits
# after the target handshake (`-naccept 1`), so the qtest itself stays in the
# foreground. The certificates are generated by build.sh.

set -eu

root=$(CDPATH= cd -- "$(dirname "$0")/../../.." && pwd)
cd "$root"

out=$root/build/tls/client
pki=$out/pki
log=$out/server.log
pidfile=$out/server.pid

if [ ! -f "$pki/server.pem" ] || [ ! -f "$pki/server.key" ]; then
    echo "tls-server: run tests/tls/client/build.sh first" >&2
    exit 2
fi
command -v openssl >/dev/null 2>&1 || {
    echo "tls-server: host openssl is required" >&2
    exit 2
}

if [ -f "$pidfile" ]; then
    kill "$(cat "$pidfile")" 2>/dev/null || true
    rm -f "$pidfile"
fi
rm -f "$log"

# Session tickets are off for this one-shot smoke. With TLS 1.3 tickets on, the
# post-handshake ticket flight exposes a netd/TCP retransmission race that
# duplicates the client's compatibility ChangeCipherSpec; s_server then aborts
# with unexpected_message. The library still offers tickets; only the test
# server disables them until the TCP retransmission path is fixed.
openssl s_server -accept 24443 -cert "$pki/server.pem" -key "$pki/server.key" \
    -no_ticket -www -naccept 1 >"$log" 2>&1 &
pid=$!
echo "$pid" > "$pidfile"

# s_server binds immediately; fail early if it died instead of letting QEMU
# time out on a connection reset.
sleep 1
if ! kill -0 "$pid" 2>/dev/null; then
    cat "$log" >&2
    echo "tls-server: s_server failed to start" >&2
    exit 1
fi
echo "tls-server: listening on 24443 (pid $pid)"
